import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate, useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [alunosPorCurso, setAlunosPorCurso] = useState({});
  const [loading, setLoading] = useState(true);
  const [expandedCurso, setExpandedCurso] = useState(null);
  const navigate = useNavigate();
  const { id } = useParams();

  const fetchCursos = async () => {
    try {
      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAlunosDoCurso = async (cursoId) => {
    try {
      const resposta = await private_api.get(`/cursos/${cursoId}/alunos`);
      if (resposta.status === 200) {
        setAlunosPorCurso((prev) => ({
          ...prev,
          [cursoId]: resposta.data,
        }));
      }
    } catch (error) {
      console.error(`Erro ao buscar alunos do curso ${cursoId}:`, error);
    }
  };

  const toggleExpandCurso = (cursoId) => {
    if (expandedCurso === cursoId) {
      setExpandedCurso(null);
    } else {
      setExpandedCurso(cursoId);
      if (!alunosPorCurso[cursoId]) {
        fetchAlunosDoCurso(cursoId);
      }
    }
  };

  useEffect(() => {
    if (id) {
      fetchCursos();
    } else {
      setLoading(false);
    }
  }, [id]);

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">Carregando...</div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active mx-3" href="">
          Cursos
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/lecionaaula/${id}`)}
        >
          Aulas
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/lecionaavaliacao/${id}`)}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>
      <table className="table table-bordered bg-white w-75">
        <thead>
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
            <th>Ações</th>
          </tr>
        </thead>
        <tbody>
          {cursos.length > 0 ? (
            cursos.map((curso) => (
              <React.Fragment key={curso.id}>
                <tr>
                  <td>{curso.nome}</td>
                  <td>{curso.nivel}</td>
                  <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                  <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                  <td>{curso.periodo}</td>
                  <td>
                    <button
                      className="btn btn-sm btn-primary"
                      onClick={() => toggleExpandCurso(curso.id)}
                    >
                      {expandedCurso === curso.id
                        ? "Ocultar alunos"
                        : "Ver alunos"}
                    </button>
                  </td>
                </tr>
                {expandedCurso === curso.id && (
                  <tr>
                    <td colSpan="6">
                      <div className="p-3">
                        <h5>Alunos matriculados:</h5>
                        {alunosPorCurso[curso.id]?.length > 0 ? (
                          <table className="table table-bordered">
                            <thead>
                              <tr>
                                <th>Nome</th>
                                <th>Email</th>
                                <th>Contacto</th>
                              </tr>
                            </thead>
                            <tbody>
                              {alunosPorCurso[curso.id].map((aluno) => (
                                <tr key={aluno.id}>
                                  <td>{aluno.utilizador?.nome}</td>
                                  <td>{aluno.utilizador?.email}</td>
                                  <td>{aluno.utilizador?.contacto}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        ) : (
                          <p>Nenhum aluno matriculado neste curso.</p>
                        )}
                      </div>
                    </td>
                  </tr>
                )}
              </React.Fragment>
            ))
          ) : (
            <tr>
              <td colSpan="6" className="text-center">
                Nenhum curso encontrado
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default LecionaLista;
